"""Transcribe reviewed non-CSLB sources and build the scoped research registers.
This is a one-time transcription helper, not a live verifier. The JSON files are
the reviewed records; rerunning requires --force and preserves unrelated sources.
"""
import json, sys
from pathlib import Path
D=Path(__file__).parent/'data'
def load(n): return json.loads((D/n).read_text())
def save(n,o): (D/n).write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
sources=load('sources.json')['rows']; by={s['id']:s for s in sources}
def src(i,url,title,publisher,kind='official-government',method='direct',supports='',limits='',official=True):
 r=dict(id=i,url=url,title=title,publisher=publisher,kind=kind,checked='2026-11-07',retrieval=method,supports=supports,limitations=limits,official=official)
 if i in by: by[i].update(r)
 else: by[i]=r;sources.append(r)
